export const tForLocale = (locale: ResolvedLanguage, key: TranslationKey, values?: Record<string, string | number>) => {
  const raw = (locale === 'zh'
    ? zh[key]
    : (mainTabConsistencyOverrides[locale]?.[key] ?? paidCoverageOverrides[locale]?.[key] ?? consumerPageCompletionOverrides[locale]?.[key] ?? supplementalOverrides[locale]?.[key] ?? overrides[locale]?.[key] ?? supplementalOverrides.en?.[key] ?? overrides.en?.[key] ?? zh[key])) as string;
  return Object.entries(values ?? {}).reduce((text, [name, value]) => text.replaceAll(`{${name}}`, String(value)), raw);
};

export const localeName = (locale: ResolvedLanguage) =>
  locale === 'zh' ? '简体中文' : locale === 'en' ? 'English' : localizedLanguageNames[locale];

export const useI18n = () => {
  const [preference, setPreference] = useState(() => readLanguagePreference());

  useEffect(() => {
    const refresh = () => setPreference(readLanguagePreference());
    window.addEventListener(LANGUAGE_PREFERENCE_EVENT, refresh);
    window.addEventListener('storage', refresh);
    return () => {
      window.removeEventListener(LANGUAGE_PREFERENCE_EVENT, refresh);
      window.removeEventListener('storage', refresh);
    };
  }, []);

  const locale = resolveLanguagePreference(preference);
  useEffect(() => {
    document.documentElement.lang = locale;
    document.documentElement.dir = locale === 'ar' || locale === 'he' ? 'rtl' : 'ltr';
  }, [locale]);

  return useMemo(() => ({
    locale,
    preference,
    t: (key: TranslationKey, values?: Record<string, string | number>) => tForLocale(locale, key, values),
    goalLabel: (goal: ProductGoal) => tForLocale(locale, `goal.${goal}` as TranslationKey),
    formatMinutes: (seconds: number) => tForLocale(locale, 'common.minutes', { count: Math.max(1, Math.round(seconds / 60)) }),
  }), [locale, preference]);
};
